@dataclass(frozen=True)
class MolecularReference:
    """Exact molecular reference and the linear 2-RDM Hamiltonian."""

    statevector: np.ndarray
    exact_energy: float
    nuclear_energy: float
    exact_gamma: np.ndarray
    exact_d2: np.ndarray
    one_body: np.ndarray
    two_body: np.ndarray
    pairs: tuple[tuple[int, int], ...]
    n_spatial_orbitals: int
    n_spin_orbitals: int
    n_alpha: int
    n_beta: int
    orbital_irreps: tuple[int, ...]
    molecule: Any | None = None
    mean_field: Any | None = None
    active_mo_coeff: np.ndarray | None = None
    n_core_orbitals: int = 0

    @property
    def n_electrons(self) -> int:
        return self.n_alpha + self.n_beta


@dataclass(frozen=True)
class PairVectorDesign:
    """Implicit quadratic shadow design backed only by pair vectors.

    A row generated by ``v`` predicts ``v.conj().T @ D @ v``.  Keeping that
    representation avoids materializing the much larger CSR matrix whose row
    is ``vec(v v.conj().T)``.  For the real frames used by the original
    protocol this is identical to the real-transpose expression; retaining
    the conjugate makes the same representation valid for complex fermionic
    shadow frames.
    """

    pair_vectors: np.ndarray

    @property
    def shape(self) -> tuple[int, int]:
        vectors = np.asarray(self.pair_vectors)
        return vectors.shape[0], vectors.shape[1] ** 2

    def __matmul__(self, vector: np.ndarray) -> np.ndarray:
        values = np.asarray(vector, dtype=float)
        n_pairs = np.asarray(self.pair_vectors).shape[1]
        if values.shape != (n_pairs * n_pairs,):
            raise ValueError("Implicit shadow design expects a flattened D2 matrix.")
        d2 = values.reshape((n_pairs, n_pairs), order="C")
        predictions = np.einsum(
            "ni,ij,nj->n",
            np.conjugate(self.pair_vectors),
            d2,
            self.pair_vectors,
            optimize=True,
        )
        # A physical real-symmetric D2 gives a real diagonal observable even
        # when the measurement frame is complex.  Discard only roundoff-level
        # imaginary parts and fail loudly for an inconsistent input instead of
        # silently handing complex values to the real SDP.
        if np.max(np.abs(np.imag(predictions)), initial=0.0) > 1e-9:
            raise ValueError("Complex shadow predictions are not real-valued.")
        return np.asarray(np.real(predictions), dtype=float)


@dataclass(frozen=True)
class ShadowData:
    """Exact or finite-shot diagonal 2-RDM data in random orbital bases."""

    rotations: tuple[np.ndarray, ...]
    pair_vectors: np.ndarray
    design: sparse.csr_matrix | PairVectorDesign
    values: np.ndarray
    lower_bounds: np.ndarray
    upper_bounds: np.ndarray
    hits: np.ndarray
    shots_per_basis: int
    exact_values: np.ndarray
    exact_constraints: bool = False
    occupations: np.ndarray | None = None

    @property
    def shot_budget(self) -> int:
        return len(self.rotations) * self.shots_per_basis

    @property
    def n_shadows(self) -> int:
        return len(self.rotations)

    def predict(self, d2: np.ndarray) -> np.ndarray:
        return np.asarray(self.design @ d2.ravel(order="C")).ravel()


@dataclass(frozen=True)
class WeightedFitStatistics:
    """TSQR factor for an exact variance-weighted shadow RMSE.

    If ``z`` contains the independent entries ``D[rows, cols]``, then

        ||residual_factor @ [z, 1]||_2

    equals the full variance-normalized residual RMSE over every observation.
    """

    rows: np.ndarray
    cols: np.ndarray
    residual_factor: np.ndarray
    observation_count: int

    def weighted_rmse(self, d2: np.ndarray) -> float:
        variables = np.asarray(d2, dtype=float)[self.rows, self.cols]
        augmented = np.concatenate((variables, np.ones(1, dtype=float)))
        return float(np.linalg.norm(self.residual_factor @ augmented))


@dataclass(frozen=True)
class SDPResult:
    """Result returned by the DQG semidefinite programs."""

    d2: np.ndarray
    gamma: np.ndarray
    energy: float
    status: str
    fit_status: str | None
    slack_sum: float | None
    solver: str
    linear_fit_status: str | None = None
    linear_max_slack: float | None = None
    linear_max_absolute_violation: float | None = None
    linear_max_normalized_violation: float | None = None
    corrected_d2: np.ndarray | None = None
    shadow_error_trace: float | None = None
    shadow_error_weight: float | None = None
    weighted_fit_optimum_rmse: float | None = None
    weighted_fit_final_rmse: float | None = None


@dataclass(frozen=True)
class LinearRDMConstraints:
    """Affine RDM bands imposed explicitly inside the SDP.

    Each row represents

        lower <= d2_map @ vec(D2) + gamma_map @ vec(gamma) <= upper.

    ``scale[i]`` is always used to nondimensionalize row ``i`` before it
    reaches the conic solver. With ``allow_minimax_relaxation``, a single
    nonnegative scalar additionally widens row ``i`` by ``scale[i] * slack``.
    The SDP first minimizes that scalar, then minimizes the molecular energy
    at the best attainable band fit.
    """

    d2_map: sparse.spmatrix | np.ndarray
    lower_bounds: np.ndarray
    upper_bounds: np.ndarray
    gamma_map: sparse.spmatrix | np.ndarray | None = None
    scales: np.ndarray | None = None
    allow_minimax_relaxation: bool = False
    name: str = "linear_rdm_band"


@dataclass(frozen=True)
class AffineRDMObjective:
    """Scaled affine RDM residual used as a convex least-squares objective.

    The objective is

        ||(d2_map vec(D2) + gamma_map vec(gamma) + offset) / scales||_2^2.

    It is useful for Hamiltonian-aware diagnostics such as a classically
    closed ACSE residual, while keeping raw measurement likelihood constraints
    separate from the model-based selection criterion.
    """

    d2_map: sparse.spmatrix | np.ndarray
    offset: np.ndarray
    gamma_map: sparse.spmatrix | np.ndarray | None = None
    scales: np.ndarray | None = None
    name: str = "affine_rdm_least_squares"


def pair_basis(n_modes: int) -> tuple[tuple[int, int], ...]:
    return tuple(combinations(range(n_modes), 2))


def _grouped_indices(labels: Sequence[tuple[int, int]]) -> tuple[np.ndarray, ...]:
    groups: dict[tuple[int, int], list[int]] = {}
    for index, label in enumerate(labels):
        groups.setdefault(tuple(label), []).append(index)
    return tuple(
        np.asarray(groups[label], dtype=int) for label in sorted(groups)
    )


def rdm_symmetry_blocks(reference: Any) -> dict[str, tuple[np.ndarray, ...]]:
    """Return exact spin/irrep blocks for D/Q, gamma, and G positivity."""

    n_spatial = int(reference.n_spatial_orbitals)
    n_modes = int(reference.n_spin_orbitals)
    if n_modes != 2 * n_spatial:
        raise ValueError("Spin-orbital symmetry blocks require two spin sectors.")
    spatial_irreps = tuple(int(value) for value in reference.orbital_irreps)
    if len(spatial_irreps) != n_spatial:
        raise ValueError("orbital_irreps must contain one label per spatial orbital.")
    spin_irreps = spatial_irreps + spatial_irreps
    spin = tuple(int(index >= n_spatial) for index in range(n_modes))
    gamma_labels = tuple(
        (spin[index], spin_irreps[index]) for index in range(n_modes)
    )
    pair_labels = tuple(
        (
            int(first < n_spatial) + int(second < n_spatial),
            spin_irreps[first] ^ spin_irreps[second],
        )
        for first, second in reference.pairs
    )
    g_labels = tuple(
        (
            spin[first] - spin[second],
            spin_irreps[first] ^ spin_irreps[second],
        )
        for first in range(n_modes)
        for second in range(n_modes)
    )
    return {
        "d2": _grouped_indices(pair_labels),
        "gamma": _grouped_indices(gamma_labels),
        "g": _grouped_indices(g_labels),
    }


def _pair_lookup(
    left: int,
    right: int,
    pair_to_index: dict[tuple[int, int], int],
) -> tuple[int | None, int]:
    if left == right:
        return None, 0
    if left < right:
        return pair_to_index[(left, right)], 1
    return pair_to_index[(right, left)], -1


def _annihilate(state: np.ndarray, mode: int) -> np.ndarray:
    """Apply a Jordan-Wigner fermionic annihilator to a statevector."""

    result = np.zeros_like(state)
    lower_mask = (1 << mode) - 1
    for basis_state in np.flatnonzero(state):
        if not (basis_state >> mode) & 1:
            continue
        parity = (basis_state & lower_mask).bit_count() & 1
        target = basis_state ^ (1 << mode)
        result[target] = (-1 if parity else 1) * state[basis_state]
    return result


def rdms_from_statevector(
    statevector: np.ndarray,
    n_modes: int,
    pairs: Sequence[tuple[int, int]] | None = None,
) -> tuple[np.ndarray, np.ndarray]:
    """Return the 1-RDM and pair-basis 2-RDM of a pure state."""

    if pairs is None:
        pairs = pair_basis(n_modes)
    one_hole_states = np.column_stack(
        [_annihilate(statevector, mode) for mode in range(n_modes)]
    )
    pair_hole_states = np.column_stack(
        [
            _annihilate(_annihilate(statevector, first), second)
            for first, second in pairs
        ]
    )
    gamma = one_hole_states.conj().T @ one_hole_states
    d2 = pair_hole_states.conj().T @ pair_hole_states
    return np.real_if_close(gamma).real, np.real_if_close(d2).real


def rdms_from_pyscf_spin_blocks(
    dm1s: Sequence[np.ndarray],
    dm2s: Sequence[np.ndarray],
    n_spatial: int,
    pairs: Sequence[tuple[int, int]] | None = None,
) -> tuple[np.ndarray, np.ndarray]:
    """Convert PySCF spin-resolved RDM blocks to the pair-basis convention.

    PySCF uses ``dm2[p,q,r,s] = <p^+ r^+ s q>``.  A pair-basis entry for
    row ``(p,r)`` and column ``(q,s)`` is the same expectation value.  Fixed
    alpha/beta particle numbers make matrix elements between different spin
    sectors vanish.
    """

    if n_spatial < 1:
        raise ValueError("n_spatial must be positive.")
    if len(dm1s) != 2 or len(dm2s) != 3:
        raise ValueError("Expected two 1-RDM and three 2-RDM spin blocks.")
    one_alpha, one_beta = (np.asarray(block) for block in dm1s)
    two_aa, two_ab, two_bb = (np.asarray(block) for block in dm2s)
    one_shape = (n_spatial, n_spatial)
    two_shape = (n_spatial,) * 4
    if one_alpha.shape != one_shape or one_beta.shape != one_shape:
        raise ValueError("A PySCF spin 1-RDM block has an incompatible shape.")
    if any(block.shape != two_shape for block in (two_aa, two_ab, two_bb)):
        raise ValueError("A PySCF spin 2-RDM block has an incompatible shape.")

    n_modes = 2 * n_spatial
    pair_tuple = pair_basis(n_modes) if pairs is None else tuple(pairs)
    gamma = np.zeros((n_modes, n_modes), dtype=float)
    gamma[:n_spatial, :n_spatial] = np.real_if_close(one_alpha.T).real
    gamma[n_spatial:, n_spatial:] = np.real_if_close(one_beta.T).real
    d2 = np.zeros((len(pair_tuple), len(pair_tuple)), dtype=float)

    def sector(pair: tuple[int, int]) -> tuple[str, int, int]:
        first, second = pair
        if not 0 <= first < second < n_modes:
            raise ValueError("pairs must contain ordered spin-orbital indices.")
        if second < n_spatial:
            return "aa", first, second
        if first >= n_spatial:
            return "bb", first - n_spatial, second - n_spatial
        return "ab", first, second - n_spatial

    sectors = tuple(sector(pair) for pair in pair_tuple)
    for row, (row_sector, first, second) in enumerate(sectors):
        for col, (col_sector, third, fourth) in enumerate(sectors):
            if row_sector != col_sector:
                continue
            if row_sector == "aa":
                value = two_aa[first, third, second, fourth]
            elif row_sector == "bb":
                value = two_bb[first, third, second, fourth]
            else:
                value = two_ab[first, third, second, fourth]
            d2[row, col] = float(np.real_if_close(value).real)
    return 0.5 * (gamma + gamma.T), 0.5 * (d2 + d2.T)


def contract_one_rdm(
    d2: np.ndarray,
    n_modes: int,
    n_electrons: int,
    pairs: Sequence[tuple[int, int]] | None = None,
) -> np.ndarray:
    """Contract a pair-basis 2-RDM to the 1-RDM."""

    if n_electrons < 2:
        raise ValueError("At least two electrons are required for a 2-RDM contraction.")
    if pairs is None:
        pairs = pair_basis(n_modes)
    pair_to_index = {pair: index for index, pair in enumerate(pairs)}
    gamma = np.zeros((n_modes, n_modes), dtype=float)
    for first in range(n_modes):
        for third in range(n_modes):
            for second in range(n_modes):
                row, row_sign = _pair_lookup(first, second, pair_to_index)
                col, col_sign = _pair_lookup(third, second, pair_to_index)
                if row is not None and col is not None:
                    gamma[first, third] += row_sign * col_sign * d2[row, col]
    return gamma / (n_electrons - 1)


def dqg_matrices(
    d2: np.ndarray,
    gamma: np.ndarray,
    pairs: Sequence[tuple[int, int]],
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """Build numerical D, Q, and G matrices using the SDP conventions."""

    n_modes = gamma.shape[0]
    pair_to_index = {pair: index for index, pair in enumerate(pairs)}

    def full_d(first: int, second: int, third: int, fourth: int) -> float:
        row, row_sign = _pair_lookup(first, second, pair_to_index)
        col, col_sign = _pair_lookup(third, fourth, pair_to_index)
        if row is None or col is None:
            return 0.0
        return float(row_sign * col_sign * d2[row, col])

    q2 = np.zeros_like(d2)
    for row, (first, second) in enumerate(pairs):
        for col, (third, fourth) in enumerate(pairs):
            q2[row, col] = (
                (second == fourth) * (first == third)
                - (first == fourth) * (second == third)
                - (second == fourth) * gamma[third, first]
                + (first == fourth) * gamma[third, second]
                + (second == third) * gamma[fourth, first]
                - (first == third) * gamma[fourth, second]
                + d2[col, row]
            )

    g2 = np.zeros((n_modes * n_modes, n_modes * n_modes), dtype=float)
    for first in range(n_modes):
        for second in range(n_modes):
            row = first * n_modes + second
            for third in range(n_modes):
                for fourth in range(n_modes):
                    col = third * n_modes + fourth
                    g2[row, col] = (
                        (first == third) * gamma[second, fourth]
                        - full_d(second, third, fourth, first)
                    )
    return d2, 0.5 * (q2 + q2.T), 0.5 * (g2 + g2.T)


def _hamiltonian_coefficients(
    fermionic_hamiltonian,
    n_modes: int,
    pairs: Sequence[tuple[int, int]],
) -> tuple[np.ndarray, np.ndarray]:
    """Convert a Qiskit Nature FermionicOp to gamma and pair-D coefficients."""

    pair_to_index = {pair: index for index, pair in enumerate(pairs)}
    one_body = np.zeros((n_modes, n_modes), dtype=float)
    two_body = np.zeros((len(pairs), len(pairs)), dtype=float)
    for term, coefficient in fermionic_hamiltonian.terms():
        value = float(np.real_if_close(coefficient).real)
        if len(term) == 2 and tuple(label for label, _ in term) == ("+", "-"):
            first, second = (index for _, index in term)
            one_body[first, second] += value
            continue
        if len(term) != 4 or tuple(label for label, _ in term) != (
            "+",
            "+",
            "-",
            "-",
        ):
            raise ValueError(f"Unsupported Hamiltonian term: {term}")
        first, second, third, fourth = (index for _, index in term)
        row, row_sign = _pair_lookup(first, second, pair_to_index)
        col, col_sign = _pair_lookup(fourth, third, pair_to_index)
        if row is not None and col is not None:
            two_body[row, col] += value * row_sign * col_sign
    return 0.5 * (one_body + one_body.T), 0.5 * (two_body + two_body.T)


def rdm_energy(
    d2: np.ndarray,
    gamma: np.ndarray,
    one_body: np.ndarray,
    two_body: np.ndarray,
    nuclear_energy: float,
) -> float:
    electronic = np.sum(one_body * gamma) + np.sum(two_body * d2)
    return float(electronic + nuclear_energy)


def _canonicalize_mo_signs(coefficients: np.ndarray) -> np.ndarray:
    """Fix the arbitrary sign gauge of real molecular orbitals."""

    canonical = np.asarray(coefficients).copy()
    for orbital in range(canonical.shape[1]):
        significant = np.flatnonzero(np.abs(canonical[:, orbital]) > 1e-10)
        if not len(significant):
            continue
        pivot = int(significant[0])
        if canonical[pivot, orbital] < 0.0:
            canonical[:, orbital] *= -1.0
    return canonical


def _canonicalize_statevector_phase(statevector: np.ndarray) -> np.ndarray:
    canonical = np.asarray(statevector).copy()
    pivot = int(np.argmax(np.abs(canonical)))
    if abs(canonical[pivot]) == 0.0:
        return canonical
    canonical *= np.exp(-1j * np.angle(canonical[pivot]))
    return np.real_if_close(canonical)


def build_h4_reference(
    long_edge: float = 1.05,
    short_edge: float = 0.65,
) -> MolecularReference:
    """Build the rectangular H4/STO-3G FCI reference used by the Maple example."""

    geometry = (
        f"H 0 0 0; H {long_edge} 0 0; "
        f"H 0 {short_edge} 0; H {long_edge} {short_edge} 0"
    )
    driver = PySCFDriver(
        atom=geometry,
        basis="sto3g",
        charge=0,
        spin=0,
        unit=DistanceUnit.ANGSTROM,
    )
    driver.run_pyscf()
    driver._calc.mo_coeff = _canonicalize_mo_signs(driver._calc.mo_coeff)
    problem = driver.to_problem()
    n_spatial = int(problem.num_spatial_orbitals)
    n_modes = int(problem.num_spin_orbitals)
    n_alpha, n_beta = (int(value) for value in problem.num_particles)
    symmetry_molecule = gto.M(
        atom=geometry,
        basis="sto3g",
        charge=0,
        spin=0,
        unit="Angstrom",
        symmetry=True,
        verbose=0,
    )
    orbital_labels = symm.label_orb_symm(
        symmetry_molecule,
        symmetry_molecule.irrep_name,
        symmetry_molecule.symm_orb,
        driver._calc.mo_coeff,
        check=True,
    )
    orbital_irreps = tuple(
        int(symm.irrep_name2id(symmetry_molecule.groupname, label))
        for label in orbital_labels
    )
    fermionic_hamiltonian = problem.hamiltonian.second_q_op()
    qubit_hamiltonian = JordanWignerMapper().map(fermionic_hamiltonian)
    hamiltonian = qubit_hamiltonian.to_matrix(sparse=True)

    alpha_mask = (1 << n_spatial) - 1
    sector = np.array(
        [
            state
            for state in range(1 << n_modes)
            if (state & alpha_mask).bit_count() == n_alpha
            and ((state >> n_spatial) & alpha_mask).bit_count() == n_beta
        ],
        dtype=int,
    )
    sector_hamiltonian = hamiltonian[sector, :][:, sector].toarray()
    eigenvalues, eigenvectors = np.linalg.eigh(sector_hamiltonian)
    statevector = np.zeros(1 << n_modes, dtype=complex)
    statevector[sector] = eigenvectors[:, 0]
    statevector /= np.linalg.norm(statevector)
    statevector = _canonicalize_statevector_phase(statevector)

    pairs = pair_basis(n_modes)
    gamma, d2 = rdms_from_statevector(statevector, n_modes, pairs)
    one_body, two_body = _hamiltonian_coefficients(
        fermionic_hamiltonian, n_modes, pairs
    )
    nuclear_energy = float(problem.nuclear_repulsion_energy)
    exact_energy = float(eigenvalues[0] + nuclear_energy)
    reconstructed_energy = rdm_energy(
        d2, gamma, one_body, two_body, nuclear_energy
    )
    if not np.isclose(exact_energy, reconstructed_energy, atol=1e-9):
        raise RuntimeError(
            "The Qiskit Hamiltonian and the internal 2-RDM convention disagree: "
            f"{exact_energy} versus {reconstructed_energy}."
        )

    return MolecularReference(
        statevector=statevector,
        exact_energy=exact_energy,
        nuclear_energy=nuclear_energy,
        exact_gamma=gamma,
        exact_d2=d2,
        one_body=one_body,
        two_body=two_body,
        pairs=pairs,
        n_spatial_orbitals=n_spatial,
        n_spin_orbitals=n_modes,
        n_alpha=n_alpha,
        n_beta=n_beta,
        orbital_irreps=orbital_irreps,
        molecule=symmetry_molecule,
        mean_field=driver._calc,
        active_mo_coeff=np.asarray(driver._calc.mo_coeff[:, :n_spatial]),
        n_core_orbitals=0,
    )


def build_n2_reference(
    bond_length: float = 1.75,
    basis: str = "cc-pvdz",
    active_electrons: int = 10,
    active_orbitals: int = 8,
    active_orbital_signs: Sequence[float] | None = None,
) -> MolecularReference:
    """Build an N2/cc-pVDZ CASCI reference from canonical RHF orbitals.

    ``CAS(10,8)`` freezes the two nitrogen 1s core orbitals and reproduces the
    active space used in arXiv:2312.11715. ``CAS(6,6)`` freezes four occupied
    orbitals and selects the six 2p-derived bonding/antibonding valence
    orbitals.
    """

    if active_electrons < 2 or active_electrons % 2:
        raise ValueError(
            "The spin-singlet N2 path requires a positive even active-electron count."
        )
    if active_orbitals < 1 or active_electrons > 2 * active_orbitals:
        raise ValueError(
            "The active space must have enough spatial orbitals for its electrons."
        )
    geometry = (
        f"N 0 0 {-bond_length / 2.0}; "
        f"N 0 0 {bond_length / 2.0}"
    )
    molecule = gto.M(
        atom=geometry,
        basis=basis,
        charge=0,
        spin=0,
        unit="Angstrom",
        symmetry="D2h",
        verbose=0,
    )
    mean_field = scf.RHF(molecule).run()
    mo_coeff = _canonicalize_mo_signs(mean_field.mo_coeff)
    if active_electrons > molecule.nelectron:
        raise ValueError("Active electrons cannot exceed the molecular electron count.")
    n_core = (molecule.nelectron - active_electrons) // 2
    if n_core + active_orbitals > mean_field.mo_coeff.shape[1]:
        raise ValueError(
            "The requested frozen-core plus active space exceeds the RHF MO space."
        )
    if active_orbital_signs is not None:
        signs = np.asarray(active_orbital_signs, dtype=float)
        if signs.shape != (active_orbitals,) or not np.all(np.abs(signs) == 1.0):
            raise ValueError("Active-orbital signs must contain one +/-1 per orbital.")
        mo_coeff = mo_coeff.copy()
        mo_coeff[:, n_core : n_core + active_orbitals] *= signs[None, :]
    mean_field.mo_coeff = mo_coeff
    casci = mcscf.CASCI(mean_field, active_orbitals, active_electrons)
    casci.ncore = n_core
    casci.kernel()

    n_alpha = active_electrons // 2
    n_beta = active_electrons // 2
    n_modes = 2 * active_orbitals
    alpha_strings = fci.cistring.make_strings(range(active_orbitals), n_alpha)
    beta_strings = fci.cistring.make_strings(range(active_orbitals), n_beta)
    statevector = np.zeros(1 << n_modes, dtype=complex)
    for alpha_index, alpha_string in enumerate(alpha_strings):
        for beta_index, beta_string in enumerate(beta_strings):
            basis_state = int(alpha_string) | (int(beta_string) << active_orbitals)
            statevector[basis_state] = casci.ci[alpha_index, beta_index]
    statevector /= np.linalg.norm(statevector)
    statevector = _canonicalize_statevector_phase(statevector)

    pairs = pair_basis(n_modes)
    gamma, d2 = rdms_from_statevector(statevector, n_modes, pairs)
    one_electron, core_energy = casci.get_h1eff()
    two_electron = ao2mo.restore(1, casci.get_h2eff(), active_orbitals)
    active_hamiltonian = ElectronicEnergy.from_raw_integrals(
        one_electron, two_electron
    ).second_q_op()
    one_body, two_body = _hamiltonian_coefficients(
        active_hamiltonian, n_modes, pairs
    )

    orbital_labels = symm.label_orb_symm(
        molecule,
        molecule.irrep_name,
        molecule.symm_orb,
        mean_field.mo_coeff,
        check=True,
    )
    active_labels = orbital_labels[n_core : n_core + active_orbitals]
    orbital_irreps = tuple(
        int(symm.irrep_name2id(molecule.groupname, label))
        for label in active_labels
    )
    exact_energy = float(casci.e_tot)
    reconstructed_energy = rdm_energy(
        d2, gamma, one_body, two_body, float(core_energy)
    )
    if not np.isclose(exact_energy, reconstructed_energy, atol=1e-9):
        raise RuntimeError(
            "The N2 CASCI Hamiltonian and pair-basis 2-RDM disagree: "
            f"{exact_energy} versus {reconstructed_energy}."
        )

    return MolecularReference(
        statevector=statevector,
        exact_energy=exact_energy,
        nuclear_energy=float(core_energy),
        exact_gamma=gamma,
        exact_d2=d2,
        one_body=one_body,
        two_body=two_body,
        pairs=pairs,
        n_spatial_orbitals=active_orbitals,
        n_spin_orbitals=n_modes,
        n_alpha=n_alpha,
        n_beta=n_beta,
        orbital_irreps=orbital_irreps,
        molecule=molecule,
        mean_field=mean_field,
        active_mo_coeff=np.asarray(
            mean_field.mo_coeff[:, n_core : n_core + active_orbitals]
        ),
        n_core_orbitals=n_core,
    )


def random_orthogonal_rotations(
    n_orbitals: int,
    count: int,
    seed: int,
) -> tuple[np.ndarray, ...]:
    """Generate Haar-distributed real orthogonal orbital rotations."""

    if count < 1:
        raise ValueError("At least one shadow basis is required.")
    rng = np.random.default_rng(seed)
    rotations: list[np.ndarray] = []
    for _ in range(count):
        q_matrix, r_matrix = np.linalg.qr(rng.normal(size=(n_orbitals, n_orbitals)))
        signs = np.where(np.diag(r_matrix) < 0.0, -1.0, 1.0)
        rotations.append(q_matrix @ np.diag(signs))
    return tuple(rotations)


def spin_orbital_rotation(spatial_rotation: np.ndarray) -> np.ndarray:
    """Apply the same spatial rotation to alpha and beta spin orbitals."""

    zero = np.zeros_like(spatial_rotation)
    return np.block([[spatial_rotation, zero], [zero, spatial_rotation]])


def exterior_square(
    one_particle_rotation: np.ndarray,
    pairs: Sequence[tuple[int, int]],
) -> np.ndarray:
    """Return the two-particle exterior representation of a rotation.

    Rows are input pairs and columns are measured output pairs, matching
    Qiskit Nature's BogoliubovTransform convention.
    """

    rotation = np.asarray(one_particle_rotation)
    result = np.empty(
        (len(pairs), len(pairs)),
        dtype=np.result_type(rotation.dtype, np.float64),
    )
    for row, (first, second) in enumerate(pairs):
        for col, (third, fourth) in enumerate(pairs):
            result[row, col] = (
                rotation[first, third] * rotation[second, fourth]
                - rotation[first, fourth] * rotation[second, third]
            )
    return result


def observation_matrices(
    rotations: Sequence[np.ndarray],
    n_spatial_orbitals: int,
    pairs: Sequence[tuple[int, int]],
) -> np.ndarray:
    """Build all linear shadow observables, one per measured orbital pair."""

    vectors = shadow_pair_vectors(rotations, n_spatial_orbitals, pairs)
    return np.asarray(
        [np.real(np.outer(np.conjugate(vector), vector)) for vector in vectors]
    )


def shadow_pair_vectors(
    rotations: Sequence[np.ndarray],
    n_spatial_orbitals: int,
    pairs: Sequence[tuple[int, int]],
) -> np.ndarray:
    """Return pair-rotation columns defining every diagonal shadow value."""

    vectors: list[np.ndarray] = []
    for spatial_rotation in rotations:
        if spatial_rotation.shape != (n_spatial_orbitals, n_spatial_orbitals):
            raise ValueError("A spatial rotation has the wrong shape.")
        spin_rotation = spin_orbital_rotation(spatial_rotation)
        pair_rotation = exterior_square(spin_rotation, pairs)
        vectors.extend(pair_rotation.T)
    return np.asarray(vectors)


def quadratic_design(
    pair_vectors: np.ndarray,
    zero_tolerance: float = 1e-14,
) -> sparse.csr_matrix:
    """Build a sparse matrix A such that A vec(D) gives all shadows."""

    n_observations, n_pairs = pair_vectors.shape
    supports = [
        np.flatnonzero(np.abs(vector) > zero_tolerance)
        for vector in pair_vectors
    ]
    total_nonzero = sum(len(support) ** 2 for support in supports)
    rows = np.empty(total_nonzero, dtype=np.int32)
    cols = np.empty(total_nonzero, dtype=np.int32)
    data = np.empty(total_nonzero, dtype=float)
    offset = 0
    for observation, (vector, support) in enumerate(zip(pair_vectors, supports)):
        block_size = len(support) ** 2
        selection = vector[support]
        rows[offset : offset + block_size] = observation
        cols[offset : offset + block_size] = (
            support[:, None] * n_pairs + support[None, :]
        ).ravel()
        data[offset : offset + block_size] = np.real(
            np.outer(np.conjugate(selection), selection)
        ).ravel()
        offset += block_size
    return sparse.coo_matrix(
        (data, (rows, cols)),
        shape=(n_observations, n_pairs * n_pairs),
    ).tocsr()


def exact_shadows(
    reference: MolecularReference,
    rotations: Sequence[np.ndarray],
) -> ShadowData:
    """Generate the noiseless expectation-value shadows used in the paper."""

    pair_vectors = shadow_pair_vectors(
        rotations, reference.n_spatial_orbitals, reference.pairs
    )
    design = quadratic_design(pair_vectors)
    values = np.asarray(design @ reference.exact_d2.ravel(order="C")).ravel()
    return ShadowData(
        rotations=tuple(np.asarray(rotation) for rotation in rotations),
        pair_vectors=pair_vectors,
        design=design,
        values=values,
        lower_bounds=values.copy(),
        upper_bounds=values.copy(),
        hits=np.full(values.shape, -1, dtype=int),
        shots_per_basis=0,
        exact_values=values.copy(),
        exact_constraints=True,
    )


def _canonical_symmetric_eigenbasis(
    matrix: np.ndarray,
    degeneracy_tolerance: float = 1e-8,
) -> tuple[np.ndarray, np.ndarray]:
    """Return a deterministic eigenbasis, including within degenerate spaces."""

    eigenvalues, eigenvectors = np.linalg.eigh(matrix)
    dimension = len(eigenvalues)
    canonical = np.zeros_like(eigenvectors)
    start = 0
    while start < dimension:
        stop = start + 1
        while (
            stop < dimension
            and abs(eigenvalues[stop] - eigenvalues[start]) <= degeneracy_tolerance
        ):
            stop += 1
        projector = eigenvectors[:, start:stop] @ eigenvectors[:, start:stop].T
        columns: list[np.ndarray] = []
        for axis in range(dimension):
            candidate = projector[:, axis].copy()
            for column in columns:
                candidate -= column * float(column @ candidate)
            norm = float(np.linalg.norm(candidate))
            if norm <= 1e-10:
                continue
            candidate /= norm
            pivot = int(np.argmax(np.abs(candidate)))
            if candidate[pivot] < 0.0:
                candidate *= -1.0
            columns.append(candidate)
            if len(columns) == stop - start:
                break
        if len(columns) != stop - start:
            raise RuntimeError("Failed to construct a canonical degenerate eigenbasis.")
        canonical[:, start:stop] = np.column_stack(columns)
        start = stop
    return eigenvalues, canonical


def gaussian_noisy_shadows(
    reference: MolecularReference,
    rotations: Sequence[np.ndarray],
    shots_per_basis: int,
    seed: int,
    probability_model: str = "natural-pair-geometric",
    noisy_d2: np.ndarray | None = None,
) -> tuple[ShadowData, np.ndarray, dict[str, float | str | bool]]:
    """Generate the globally noisy 2-RDM shadows described in the paper SI.

    The SI specifies element-wise Gaussian noise with standard deviation
    ``sqrt(p * (1 - p) / N_shots)`` and states that ``p`` derives from natural
    orbital occupations. It does not specify how four 2-RDM indices map to one
    occupation probability. The default uses the geometric mean of the two
    natural-orbital pair-occupation proxies associated with a matrix element.
    """

    if shots_per_basis < 1:
        raise ValueError("shots_per_basis must be positive.")
    if probability_model not in {"natural-pair-geometric", "max-variance"}:
        raise ValueError(f"Unsupported Gaussian probability model: {probability_model}.")

    n_spatial = reference.n_spatial_orbitals
    spatial_gamma = 0.5 * (
        reference.exact_gamma[:n_spatial, :n_spatial]
        + reference.exact_gamma[:n_spatial, :n_spatial].T
    )
    occupations, natural_orbitals = _canonical_symmetric_eigenbasis(spatial_gamma)
    occupations = np.clip(occupations, 0.0, 1.0)
    natural_spin_rotation = spin_orbital_rotation(natural_orbitals)
    pair_rotation = exterior_square(natural_spin_rotation, reference.pairs)
    natural_d2 = pair_rotation.T @ reference.exact_d2 @ pair_rotation

    if probability_model == "max-variance":
        effective_probabilities = np.full(natural_d2.shape, 0.5, dtype=float)
    else:
        spin_occupations = np.concatenate([occupations, occupations])
        pair_probabilities = np.asarray(
            [
                spin_occupations[first] * spin_occupations[second]
                for first, second in reference.pairs
            ],
            dtype=float,
        )
        effective_probabilities = np.sqrt(
            pair_probabilities[:, None] * pair_probabilities[None, :]
        )
    effective_probabilities = np.clip(effective_probabilities, 0.0, 1.0)
    standard_deviations = np.sqrt(
        effective_probabilities * (1.0 - effective_probabilities) / shots_per_basis
    )

    reused_noisy_d2 = noisy_d2 is not None
    if noisy_d2 is None:
        rng = np.random.default_rng(seed)
        upper = np.triu(rng.normal(size=natural_d2.shape) * standard_deviations)
        noise = upper + np.triu(upper, 1).T
        noisy_natural_d2 = natural_d2 + noise
        noisy_d2 = pair_rotation @ noisy_natural_d2 @ pair_rotation.T
        noisy_d2 = 0.5 * (noisy_d2 + noisy_d2.T)
    else:
        noisy_d2 = np.asarray(noisy_d2, dtype=float)
        if noisy_d2.shape != reference.exact_d2.shape:
            raise ValueError("noisy_d2 must have the same shape as the exact 2-RDM.")
        noisy_d2 = 0.5 * (noisy_d2 + noisy_d2.T)

    pair_vectors = shadow_pair_vectors(
        rotations, reference.n_spatial_orbitals, reference.pairs
    )
    design = quadratic_design(pair_vectors)
    exact_values = np.asarray(
        design @ reference.exact_d2.ravel(order="C")
    ).ravel()
    values = np.asarray(design @ noisy_d2.ravel(order="C")).ravel()
    shadow_data = ShadowData(
        rotations=tuple(np.asarray(rotation) for rotation in rotations),
        pair_vectors=pair_vectors,
        design=design,
        values=values,
        lower_bounds=values.copy(),
        upper_bounds=values.copy(),
        hits=np.full(values.shape, -1, dtype=int),
        shots_per_basis=shots_per_basis,
        exact_values=exact_values,
        exact_constraints=False,
    )
    diagnostics: dict[str, float | str | bool] = {
        "probability_model": probability_model,
        "noise_frobenius_norm": float(np.linalg.norm(noisy_d2 - reference.exact_d2)),
        "sigma_min": float(np.min(standard_deviations)),
        "sigma_mean": float(np.mean(standard_deviations)),
        "sigma_max": float(np.max(standard_deviations)),
        "natural_occupation_min": float(np.min(occupations)),
        "natural_occupation_max": float(np.max(occupations)),
        "reused_noisy_d2": reused_noisy_d2,
    }
    return shadow_data, noisy_d2, diagnostics


def subset_shadows(shadow_data: ShadowData, n_shadows: int) -> ShadowData:
    """Return a prefix of a reproducible random-shadow sequence."""

    if n_shadows < 1 or n_shadows > shadow_data.n_shadows:
        raise ValueError("n_shadows must select a nonempty prefix.")
    observations_per_shadow = len(shadow_data.pair_vectors) // shadow_data.n_shadows
    stop = n_shadows * observations_per_shadow
    return ShadowData(
        rotations=shadow_data.rotations[:n_shadows],
        pair_vectors=shadow_data.pair_vectors[:stop],
        design=shadow_data.design[:stop],
        values=shadow_data.values[:stop],
        lower_bounds=shadow_data.lower_bounds[:stop],
        upper_bounds=shadow_data.upper_bounds[:stop],
        hits=shadow_data.hits[:stop],
        shots_per_basis=shadow_data.shots_per_basis,
        exact_values=shadow_data.exact_values[:stop],
        exact_constraints=shadow_data.exact_constraints,
        occupations=(
            None
            if shadow_data.occupations is None
            else shadow_data.occupations[:n_shadows]
        ),
    )


def project_shadows_to_consistent_d2(
    reference: MolecularReference,
    shadow_data: ShadowData,
    ridge: float = 1e-8,
    tolerance: float = 1e-7,
    max_iterations: int | None = None,
) -> tuple[ShadowData, np.ndarray, dict[str, float | int]]:
    """Project finite-shot frequencies onto one global symmetric 2-RDM.

    Independent measurements in many orbital bases are generally inconsistent
    with exact equalities for any single matrix.  The nuclear-norm model in
    Eq. (11) of arXiv:2511.09717 instead assumes all shadows derive from one
    globally perturbed 2-RDM.  This sparse ridge projection supplies that
    consistent input while preserving the measured row-space information.
    """

    if ridge < 0.0:
        raise ValueError("ridge cannot be negative.")
    if tolerance <= 0.0:
        raise ValueError("tolerance must be positive.")
    n_pairs = len(reference.pairs)
    n_spatial = reference.n_spatial_orbitals
    pair_alpha_count = np.array(
        [
            int(first < n_spatial) + int(second < n_spatial)
            for first, second in reference.pairs
        ]
    )
    variables = [
        (row, col)
        for row in range(n_pairs)
        for col in range(row, n_pairs)
        if pair_alpha_count[row] == pair_alpha_count[col]
    ]
    primary_columns = np.asarray(
        [row * n_pairs + col for row, col in variables], dtype=int
    )
    secondary_columns = np.asarray(
        [col * n_pairs + row for row, col in variables], dtype=int
    )
    off_diagonal = (primary_columns != secondary_columns).astype(float)
    symmetric_design = shadow_data.design[:, primary_columns].tocsr()
    symmetric_design = symmetric_design + (
        shadow_data.design[:, secondary_columns]
        @ sparse.diags(off_diagonal, format="csr")
    )
    iteration_limit = (
        max_iterations
        if max_iterations is not None
        else max(1000, 4 * len(variables))
    )
    if iteration_limit < 1:
        raise ValueError("max_iterations must be positive.")
    solution = sparse.linalg.lsqr(
        symmetric_design,
        shadow_data.values,
        damp=math.sqrt(ridge),
        atol=tolerance,
        btol=tolerance,
        iter_lim=iteration_limit,
    )
    coefficients = np.asarray(solution[0], dtype=float)
    projected_d2 = np.zeros((n_pairs, n_pairs), dtype=float)
    for value, (row, col) in zip(coefficients, variables):
        projected_d2[row, col] = value
        projected_d2[col, row] = value
    projected_values = shadow_data.predict(projected_d2)
    residual = projected_values - shadow_data.values
    projected = ShadowData(
        rotations=shadow_data.rotations,
        pair_vectors=shadow_data.pair_vectors,
        design=shadow_data.design,
        values=projected_values,
        lower_bounds=projected_values.copy(),
        upper_bounds=projected_values.copy(),
        hits=shadow_data.hits,
        shots_per_basis=shadow_data.shots_per_basis,
        exact_values=shadow_data.exact_values,
        exact_constraints=False,
        occupations=shadow_data.occupations,
    )
    diagnostics: dict[str, float | int] = {
        "projection_rmse": float(np.sqrt(np.mean(residual**2))),
        "lsqr_stop_code": int(solution[1]),
        "lsqr_iterations": int(solution[2]),
        "lsqr_residual_norm": float(solution[3]),
        "lsqr_normal_residual_norm": float(solution[4]),
        "lsqr_condition_estimate": float(solution[6]),
    }
    return projected, projected_d2, diagnostics


def _wilson_bounds(hits: np.ndarray, shots: int, z_score: float) -> tuple[np.ndarray, np.ndarray]:
    if shots < 1:
        raise ValueError("shots must be positive.")
    if z_score < 0.0:
        raise ValueError("z_score cannot be negative.")
    values = hits / shots
    if z_score == 0.0:
        return values.copy(), values.copy()
    z2 = z_score * z_score
    denominator = 1.0 + z2 / shots
    center = (values + z2 / (2.0 * shots)) / denominator
    half_width = (
        z_score
        * np.sqrt(values * (1.0 - values) / shots + z2 / (4.0 * shots * shots))
        / denominator
    )
    return np.maximum(0.0, center - half_width), np.minimum(1.0, center + half_width)


def _pair_hits_from_counts(
    counts: dict[str, int],
    pairs: Sequence[tuple[int, int]],
) -> np.ndarray:
    hits = np.zeros(len(pairs), dtype=int)
    for bitstring, repetitions in counts.items():
        occupation = int(bitstring.replace(" ", ""), 2)
        for index, (first, second) in enumerate(pairs):
            if (occupation >> first) & 1 and (occupation >> second) & 1:
                hits[index] += int(repetitions)
    return hits


def _occupation_samples_from_counts(
    counts: dict[str, int], shots: int
) -> np.ndarray:
    samples = np.concatenate(
        [
            np.full(
                repetitions,
                int(bitstring.replace(" ", ""), 2),
                dtype=np.uint64,
            )
            for bitstring, repetitions in counts.items()
        ]
    )
    if len(samples) != shots:
        raise RuntimeError("Aer counts do not sum to the requested shot count.")
    return samples


def bootstrap_discrepancy_cap(
    shadow_data: ShadowData,
    pairs: Sequence[tuple[int, int]],
    confidence: float = 0.95,
    replicates: int = 2000,
    seed: int = 0,
    variance_floor: float = 1e-12,
) -> tuple[float, dict[str, float | int | str]]:
    """Estimate a reference-free weighted-fit radius from raw bitstrings.

    Each orbital basis is resampled as one multinomial block, preserving the
    correlations among all pair indicators obtained from the same occupation
    shot.  No exact expectation values or additional quantum measurements are
    used.
    """

    if shadow_data.occupations is None:
        raise ValueError("Bootstrap calibration requires raw occupation samples.")
    if not 0.0 < confidence < 1.0:
        raise ValueError("confidence must lie strictly between zero and one.")
    if replicates < 1:
        raise ValueError("replicates must be positive.")
    if variance_floor <= 0.0:
        raise ValueError("variance_floor must be positive.")
    samples = np.asarray(shadow_data.occupations, dtype=np.uint64)
    if samples.shape != (shadow_data.n_shadows, shadow_data.shots_per_basis):
        raise ValueError("Raw occupation samples have an incompatible shape.")
    observations_per_shadow = len(pairs)
    if len(shadow_data.values) != shadow_data.n_shadows * observations_per_shadow:
        raise ValueError("Shadow observations do not match the supplied pair basis.")

    smoothed = (shadow_data.hits.astype(float) + 0.5) / (
        shadow_data.shots_per_basis + 1.0
    )
    variances = np.maximum(
        smoothed * (1.0 - smoothed) / shadow_data.shots_per_basis,
        variance_floor,
    )
    pair_masks = np.asarray(
        [(1 << first) | (1 << second) for first, second in pairs],
        dtype=np.uint64,
    )
    rng = np.random.default_rng(seed)
    squared_norms = np.zeros(replicates, dtype=float)
    for basis_index, basis_samples in enumerate(samples):
        occupations, multiplicities = np.unique(
            basis_samples, return_counts=True
        )
        probabilities = multiplicities / shadow_data.shots_per_basis
        multinomial_counts = rng.multinomial(
            shadow_data.shots_per_basis,
            probabilities,
            size=replicates,
        )
        pair_indicators = (
            occupations[:, None] & pair_masks[None, :]
        ) == pair_masks[None, :]
        bootstrap_values = (
            multinomial_counts @ pair_indicators.astype(float)
        ) / shadow_data.shots_per_basis
        start = basis_index * observations_per_shadow
        stop = start + observations_per_shadow
        normalized = (
            bootstrap_values - shadow_data.values[start:stop]
        ) / np.sqrt(variances[start:stop])
        squared_norms += np.sum(normalized**2, axis=1)
    bootstrap_rmse = np.sqrt(squared_norms / len(shadow_data.values))
    cap = float(np.quantile(bootstrap_rmse, confidence, method="higher"))
    return cap, {
        "method": "raw_occupation_block_bootstrap",
        "confidence": float(confidence),
        "replicates": int(replicates),
        "seed": int(seed),
        "mean": float(np.mean(bootstrap_rmse)),
        "median": float(np.median(bootstrap_rmse)),
        "cap": cap,
    }


def posterior_discrepancy_cap(
    shadow_data: ShadowData,
    pairs: Sequence[tuple[int, int]],
    confidence: float = 0.999,
    replicates: int = 10_000,
    seed: int = 0,
    prior_concentration: float = 1.0,
    variance_floor: float = 1e-12,
) -> tuple[float, dict[str, float | int | str]]:
    """Return a measurement-only discrepancy radius with unseen-state support.

    For each orbital basis, a symmetric Dirichlet posterior is constructed on
    every occupation bitstring in the observed ``(N_alpha, N_beta)`` sector.
    The total prior concentration is fixed, rather than assigned per state, so
    the regularization does not grow combinatorially with active-space size.
    Posterior draws preserve all within-shot pair correlations.
    """

    if shadow_data.occupations is None:
        raise ValueError("Posterior calibration requires raw occupation samples.")
    if not 0.0 < confidence < 1.0:
        raise ValueError("confidence must lie strictly between zero and one.")
    if replicates < 1:
        raise ValueError("replicates must be positive.")
    if prior_concentration <= 0.0:
        raise ValueError("prior_concentration must be positive.")
    if variance_floor <= 0.0:
        raise ValueError("variance_floor must be positive.")
    samples = np.asarray(shadow_data.occupations, dtype=np.uint64)
    if samples.shape != (shadow_data.n_shadows, shadow_data.shots_per_basis):
        raise ValueError("Raw occupation samples have an incompatible shape.")
    n_modes = max(max(pair) for pair in pairs) + 1
    if n_modes % 2:
        raise ValueError("Spin-orbital pair bases must contain two spin blocks.")
    n_spatial = n_modes // 2
    alpha_mask = (1 << n_spatial) - 1
    first_sample = int(samples[0, 0])
    n_alpha = (first_sample & alpha_mask).bit_count()
    n_beta = (first_sample >> n_spatial).bit_count()
    allowed_states = np.asarray(
        [
            sum(1 << orbital for orbital in alpha_occupied)
            | sum(
                1 << (n_spatial + orbital) for orbital in beta_occupied
            )
            for alpha_occupied in combinations(range(n_spatial), n_alpha)
            for beta_occupied in combinations(range(n_spatial), n_beta)
        ],
        dtype=np.uint64,
    )
    state_lookup = {
        int(occupation): index
        for index, occupation in enumerate(allowed_states)
    }
    if any(int(sample) not in state_lookup for sample in samples.ravel()):
        raise ValueError("Raw samples do not share one particle-number sector.")
    pair_masks = np.asarray(
        [(1 << first) | (1 << second) for first, second in pairs],
        dtype=np.uint64,
    )
    pair_indicators = (
        (allowed_states[:, None] & pair_masks[None, :])
        == pair_masks[None, :]
    ).astype(float)
    smoothed = (shadow_data.hits.astype(float) + 0.5) / (
        shadow_data.shots_per_basis + 1.0
    )
    variances = np.maximum(
        smoothed * (1.0 - smoothed) / shadow_data.shots_per_basis,
        variance_floor,
    )
    rng = np.random.default_rng(seed)
    squared_norms = np.zeros(replicates, dtype=float)
    prior_per_state = prior_concentration / len(allowed_states)
    observations_per_shadow = len(pairs)
    for basis_index, basis_samples in enumerate(samples):
        counts = np.zeros(len(allowed_states), dtype=float)
        occupations, multiplicities = np.unique(
            basis_samples, return_counts=True
        )
        for occupation, multiplicity in zip(occupations, multiplicities):
            counts[state_lookup[int(occupation)]] = multiplicity
        probabilities = rng.dirichlet(
            counts + prior_per_state,
            size=replicates,
        )
        posterior_values = probabilities @ pair_indicators
        start = basis_index * observations_per_shadow
        stop = start + observations_per_shadow
        normalized = (
            posterior_values - shadow_data.values[start:stop]
        ) / np.sqrt(variances[start:stop])
        squared_norms += np.sum(normalized**2, axis=1)
    posterior_rmse = np.sqrt(squared_norms / len(shadow_data.values))
    cap = float(np.quantile(posterior_rmse, confidence, method="higher"))
    return cap, {
        "method": "raw_occupation_dirichlet_posterior",
        "confidence": float(confidence),
        "replicates": int(replicates),
        "seed": int(seed),
        "prior_concentration": float(prior_concentration),
        "allowed_occupations": int(len(allowed_states)),
        "mean": float(np.mean(posterior_rmse)),
        "median": float(np.median(posterior_rmse)),
        "cap": cap,
    }


def sample_shadows(
    reference: MolecularReference,
    rotations: Sequence[np.ndarray],
    shots_per_basis: int,
    seed: int,
    confidence_z: float = 2.0,
    optimization_level: int = 1,
) -> ShadowData:
    """Prepare or inject the exact state and sample occupations with Aer.

    Small systems use a transpiled ``StatePreparation`` circuit.  For larger
    active spaces, including the 16-qubit N2 benchmark, Aer receives the exact
    statevector through its simulator-only ``set_statevector`` instruction.
    Each basis has an explicit simulator seed.  Molecular-orbital signs are
    canonicalized when the reference is built, making the seeded samples
    deterministic across independent Python processes.
    """

    if shots_per_basis < 1:
        raise ValueError("shots_per_basis must be positive.")
    inject_statevector = reference.n_spin_orbitals > 10
    state_preparation = (
        None if inject_statevector else StatePreparation(reference.statevector)
    )
    circuits: list[QuantumCircuit] = []
    for spatial_rotation in rotations:
        circuit = QuantumCircuit(reference.n_spin_orbitals, reference.n_spin_orbitals)
        if inject_statevector:
            circuit.set_statevector(reference.statevector)
        else:
            circuit.append(state_preparation, range(reference.n_spin_orbitals))
        circuit.compose(
            BogoliubovTransform(
                spin_orbital_rotation(spatial_rotation).astype(complex)
            ),
            qubits=range(reference.n_spin_orbitals),
            inplace=True,
        )
        circuit.measure(
            range(reference.n_spin_orbitals), range(reference.n_spin_orbitals)
        )
        circuits.append(circuit)

    backend = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
        max_parallel_shots=1,
    )
    compiled = transpile(
        circuits,
        backend,
        optimization_level=optimization_level,
        seed_transpiler=seed,
    )
    basis_seeds = [
        int(child.generate_state(1, dtype=np.uint32)[0])
        for child in np.random.SeedSequence(seed).spawn(len(circuits))
    ]
    counts_by_basis = [
        backend.run(
            circuit,
            shots=shots_per_basis,
            seed_simulator=basis_seed,
        )
        .result()
        .get_counts(0)
        for circuit, basis_seed in zip(compiled, basis_seeds)
    ]
    hits = np.concatenate(
        [
            _pair_hits_from_counts(counts, reference.pairs)
            for counts in counts_by_basis
        ]
    )
    occupations = np.stack(
        [
            _occupation_samples_from_counts(counts, shots_per_basis)
            for counts in counts_by_basis
        ]
    )
    values = hits / shots_per_basis
    lower, upper = _wilson_bounds(hits, shots_per_basis, confidence_z)
    pair_vectors = shadow_pair_vectors(
        rotations, reference.n_spatial_orbitals, reference.pairs
    )
    design = quadratic_design(pair_vectors)
    exact_values = np.asarray(
        design @ reference.exact_d2.ravel(order="C")
    ).ravel()
    return ShadowData(
        rotations=tuple(np.asarray(rotation) for rotation in rotations),
        pair_vectors=pair_vectors,
        design=design,
        values=values,
        lower_bounds=lower,
        upper_bounds=upper,
        hits=hits,
        shots_per_basis=shots_per_basis,
        exact_values=exact_values,
        exact_constraints=False,
        occupations=occupations,
    )


def _cvx_d_element(
    d2: cp.Expression,
    first: int,
    second: int,
    third: int,
    fourth: int,
    pair_to_index: dict[tuple[int, int], int],
):
    row, row_sign = _pair_lookup(first, second, pair_to_index)
    col, col_sign = _pair_lookup(third, fourth, pair_to_index)
    if row is None or col is None:
        return 0.0
    return row_sign * col_sign * d2[row, col]


def _solver_options(
    solver: str,
    tolerance: float,
    max_iterations: int,
    verbose: bool,
    solver_threads: int | None = None,
) -> dict:
    options: dict = {"solver": solver, "verbose": verbose, "warm_start": True}
    if solver.upper() == "SCS":
        options.update(eps=tolerance, max_iters=max_iterations)
    elif solver.upper() == "CLARABEL":
        options.update(max_iter=max_iterations)
    elif solver.upper() == "MOSEK":
        mosek_params: dict[str, int | str] = {
            "MSK_IPAR_INTPNT_MAX_ITERATIONS": max_iterations,
            "MSK_IPAR_INTPNT_SOLVE_FORM": "MSK_SOLVE_DUAL",
        }
        if solver_threads is not None:
            mosek_params["MSK_IPAR_NUM_THREADS"] = solver_threads
        options.update(eps=tolerance, mosek_params=mosek_params)
    return options


def _dqg_linear_maps(
    n_modes: int,
    pairs: Sequence[tuple[int, int]],
) -> tuple[
    sparse.csr_matrix,
    sparse.csr_matrix,
    sparse.csr_matrix,
    sparse.csr_matrix,
    np.ndarray,
]:
    """Sparse maps from vec(D), vec(gamma) to vec(Q) and vec(G)."""

    n_pairs = len(pairs)
    pair_to_index = {pair: index for index, pair in enumerate(pairs)}

    q_d_rows: list[int] = []
    q_d_cols: list[int] = []
    q_d_data: list[float] = []
    q_g_rows: list[int] = []
    q_g_cols: list[int] = []
    q_g_data: list[float] = []
    q_constant = np.zeros(n_pairs * n_pairs, dtype=float)
    for row, (first, second) in enumerate(pairs):
        for col, (third, fourth) in enumerate(pairs):
            output = row * n_pairs + col
            q_constant[output] = (
                (second == fourth) * (first == third)
                - (first == fourth) * (second == third)
            )
            q_d_rows.append(output)
            q_d_cols.append(col * n_pairs + row)
            q_d_data.append(1.0)
            gamma_terms = (
                (third, first, -(second == fourth)),
                (third, second, +(first == fourth)),
                (fourth, first, +(second == third)),
                (fourth, second, -(first == third)),
            )
            for gamma_row, gamma_col, coefficient in gamma_terms:
                if coefficient:
                    q_g_rows.append(output)
                    q_g_cols.append(gamma_row * n_modes + gamma_col)
                    q_g_data.append(float(coefficient))

    g_d_rows: list[int] = []
    g_d_cols: list[int] = []
    g_d_data: list[float] = []
    g_g_rows: list[int] = []
    g_g_cols: list[int] = []
    g_g_data: list[float] = []
    g_dimension = n_modes * n_modes
    for first in range(n_modes):
        for second in range(n_modes):
            row = first * n_modes + second
            for third in range(n_modes):
                for fourth in range(n_modes):
                    col = third * n_modes + fourth
                    output = row * g_dimension + col
                    if first == third:
                        g_g_rows.append(output)
                        g_g_cols.append(second * n_modes + fourth)
                        g_g_data.append(1.0)
                    d_row, d_row_sign = _pair_lookup(second, third, pair_to_index)
                    d_col, d_col_sign = _pair_lookup(fourth, first, pair_to_index)
                    if d_row is not None and d_col is not None:
                        g_d_rows.append(output)
                        g_d_cols.append(d_row * n_pairs + d_col)
                        g_d_data.append(float(-d_row_sign * d_col_sign))

    q_d = sparse.coo_matrix(
        (q_d_data, (q_d_rows, q_d_cols)),
        shape=(n_pairs * n_pairs, n_pairs * n_pairs),
    ).tocsr()
    q_gamma = sparse.coo_matrix(
        (q_g_data, (q_g_rows, q_g_cols)),
        shape=(n_pairs * n_pairs, n_modes * n_modes),
    ).tocsr()
    g_d = sparse.coo_matrix(
        (g_d_data, (g_d_rows, g_d_cols)),
        shape=(g_dimension * g_dimension, n_pairs * n_pairs),
    ).tocsr()
    g_gamma = sparse.coo_matrix(
        (g_g_data, (g_g_rows, g_g_cols)),
        shape=(g_dimension * g_dimension, n_modes * n_modes),
    ).tocsr()
    return q_d, q_gamma, g_d, g_gamma, q_constant


def solve_dqg_sdp(
    reference: MolecularReference,
    shadow_data: ShadowData | None = None,
    solver: str = "SCS",
    tolerance: float = 1e-4,
    max_iterations: int = 20_000,
    solver_threads: int | None = None,
    lexicographic_tolerance: float = 1e-4,
    verbose: bool = False,
    positivity_conditions: str = "DQG",
    symmetry_blocked_psd: bool = False,
    additional_d2_objective: np.ndarray | None = None,
    additional_gamma_objective: np.ndarray | None = None,
    linear_constraints: LinearRDMConstraints | None = None,
    affine_objective: AffineRDMObjective | None = None,
    linear_lexicographic_tolerance: float = 1e-5,
    linear_fit_only: bool = False,
    initial_d2: np.ndarray | None = None,
    initial_gamma: np.ndarray | None = None,
    initial_corrected_d2: np.ndarray | None = None,
    shadow_error_weight: float | None = None,
    weighted_shadow_fit: bool = False,
    shadow_variance_floor: float = 1e-12,
    weighted_fit_rmse_cap: float | None = None,
    weighted_fit_statistics: WeightedFitStatistics | None = None,
    selection_objective: str = "energy",
    selection_d2_target: np.ndarray | None = None,
) -> SDPResult:
    """Solve a v2RDM or constrained-shadow SDP at a selected positivity level.

    ``positivity_conditions`` accepts ``D``, ``DQ``, or ``DQG``. There are two
    distinct finite-data formulations. With ``shadow_error_weight``, this
    implements Eq. (11) of the 2025 constrained-shadow paper in one stage:
    minimize the selected RDM objective plus
    ``w * Tr(error_positive + error_negative)``, while exact shadow equalities
    are imposed on ``D + error_positive - error_negative``. Otherwise, noisy
    shadow data use an interval or variance-weighted fit followed by a
    lexicographic selection step. ``selection_objective`` can be
    ``closest_d2`` to select the feasible matrix nearest a supplied target.
    ``linear_rdm`` uses the supplied additional RDM objectives, and
    ``affine_least_squares`` minimizes a supplied scaled affine residual.
    """

    positivity = positivity_conditions.upper()
    if positivity not in {"D", "DQ", "DQG"}:
        raise ValueError("positivity_conditions must be one of D, DQ, or DQG.")
    if selection_objective not in {
        "energy",
        "closest_d2",
        "linear_rdm",
        "affine_least_squares",
    }:
        raise ValueError(
            "selection_objective must be 'energy', 'closest_d2', or "
            "'linear_rdm', or 'affine_least_squares'."
        )
    if (
        selection_objective == "linear_rdm"
        and additional_d2_objective is None
        and additional_gamma_objective is None
    ):
        raise ValueError(
            "selection_objective='linear_rdm' requires an additional RDM "
            "objective."
        )
    if selection_objective == "affine_least_squares" and affine_objective is None:
        raise ValueError(
            "selection_objective='affine_least_squares' requires "
            "affine_objective."
        )
    if affine_objective is not None and selection_objective != "affine_least_squares":
        raise ValueError(
            "affine_objective is only valid with "
            "selection_objective='affine_least_squares'."
        )
    if shadow_error_weight is not None:
        if shadow_error_weight <= 0.0:
            raise ValueError("shadow_error_weight must be positive.")
        if shadow_data is None:
            raise ValueError("shadow_error_weight requires shadow_data.")
    if weighted_shadow_fit and shadow_error_weight is not None:
        raise ValueError(
            "weighted_shadow_fit cannot be combined with shadow_error_weight."
        )
    if weighted_fit_rmse_cap is not None:
        if not weighted_shadow_fit:
            raise ValueError(
                "weighted_fit_rmse_cap requires weighted_shadow_fit=True."
            )
        if weighted_fit_rmse_cap <= 0.0:
            raise ValueError("weighted_fit_rmse_cap must be positive.")
    if weighted_fit_statistics is not None:
        if not weighted_shadow_fit:
            raise ValueError(
                "weighted_fit_statistics requires weighted_shadow_fit=True."
            )
        if shadow_data is not None:
            raise ValueError(
                "weighted_fit_statistics and explicit shadow_data are mutually "
                "exclusive."
            )
        if shadow_error_weight is not None:
            raise ValueError(
                "weighted_fit_statistics cannot be combined with shadow_error_weight."
            )
    if shadow_variance_floor <= 0.0:
        raise ValueError("shadow_variance_floor must be positive.")
    if solver_threads is not None and solver_threads < 1:
        raise ValueError("solver_threads must be positive when supplied.")

    n_modes = reference.n_spin_orbitals
    n_pairs = len(reference.pairs)
    n_electrons = reference.n_electrons
    n_spatial = reference.n_spatial_orbitals
    pair_to_index = {pair: index for index, pair in enumerate(reference.pairs)}
    pair_alpha_count = np.array(
        [
            int(first < n_spatial) + int(second < n_spatial)
            for first, second in reference.pairs
        ]
    )
    spin_orbital_irreps = reference.orbital_irreps + reference.orbital_irreps
    pair_irreps = np.array(
        [
            spin_orbital_irreps[first] ^ spin_orbital_irreps[second]
            for first, second in reference.pairs
        ]
    )
    psd_blocks = rdm_symmetry_blocks(reference) if symmetry_blocked_psd else None

    d2 = cp.Variable((n_pairs, n_pairs), symmetric=True, name="D")
    gamma = cp.Variable((n_modes, n_modes), symmetric=True, name="gamma")
    if initial_d2 is not None:
        value = np.asarray(initial_d2, dtype=float)
        if value.shape != (n_pairs, n_pairs):
            raise ValueError("initial_d2 must have the same shape as the 2-RDM.")
        d2.value = 0.5 * (value + value.T)
    if initial_gamma is not None:
        value = np.asarray(initial_gamma, dtype=float)
        if value.shape != (n_modes, n_modes):
            raise ValueError("initial_gamma must have the same shape as the 1-RDM.")
        gamma.value = 0.5 * (value + value.T)
    if initial_corrected_d2 is not None:
        value = np.asarray(initial_corrected_d2, dtype=float)
        if value.shape != (n_pairs, n_pairs):
            raise ValueError(
                "initial_corrected_d2 must have the same shape as the 2-RDM."
            )
    constraints: list[cp.Constraint] = [
        cp.trace(d2) == math.comb(n_electrons, 2),
        cp.trace(gamma) == n_electrons,
    ]
    if psd_blocks is None:
        constraints.extend([d2 >> 0, gamma >> 0, np.eye(n_modes) - gamma >> 0])
    else:
        for indices in psd_blocks["d2"]:
            constraints.append(d2[np.ix_(indices, indices)] >> 0)
        for indices in psd_blocks["gamma"]:
            block = gamma[np.ix_(indices, indices)]
            constraints.extend([block >> 0, np.eye(len(indices)) - block >> 0])

    for first in range(n_modes):
        for third in range(n_modes):
            contracted = sum(
                (
                    _cvx_d_element(
                        d2, first, second, third, second, pair_to_index
                    )
                    for second in range(n_modes)
                ),
                0.0,
            )
            constraints.append(contracted == (n_electrons - 1) * gamma[first, third])

    constraints.extend(
        [
            cp.trace(gamma[:n_spatial, :n_spatial]) == reference.n_alpha,
            cp.trace(gamma[n_spatial:, n_spatial:]) == reference.n_beta,
            gamma[:n_spatial, n_spatial:] == 0,
        ]
    )
    if reference.n_alpha == reference.n_beta:
        # For M_s = 0, <S^2> = N/2 - sum_pq D[p_a q_b, q_a p_b].
        # Setting this expectation to zero selects the singlet spin sector used
        # by the spin-adapted Maple Variational2RDM calculation.
        spin_exchange = sum(
            (
                _cvx_d_element(
                    d2,
                    p,
                    q + n_spatial,
                    q,
                    p + n_spatial,
                    pair_to_index,
                )
                for p in range(n_spatial)
                for q in range(n_spatial)
            ),
            0.0,
        )
        constraints.extend(
            [
                spin_exchange == n_electrons / 2,
                gamma[:n_spatial, :n_spatial]
                == gamma[n_spatial:, n_spatial:],
            ]
        )

    for first in range(n_modes):
        for third in range(first + 1, n_modes):
            if spin_orbital_irreps[first] != spin_orbital_irreps[third]:
                constraints.append(gamma[first, third] == 0)
    for row in range(n_pairs):
        for col in range(row + 1, n_pairs):
            if (
                pair_alpha_count[row] != pair_alpha_count[col]
                or pair_irreps[row] != pair_irreps[col]
            ):
                constraints.append(d2[row, col] == 0)
    sector_traces = {
        2: math.comb(reference.n_alpha, 2),
        1: reference.n_alpha * reference.n_beta,
        0: math.comb(reference.n_beta, 2),
    }
    for alpha_count, target in sector_traces.items():
        indices = np.flatnonzero(pair_alpha_count == alpha_count)
        constraints.append(cp.sum(cp.diag(d2)[indices]) == target)

    if reference.n_alpha == reference.n_beta:
        spatial_pairs = pair_basis(n_spatial)
        alpha_alpha = np.array(
            [pair_to_index[pair] for pair in spatial_pairs], dtype=int
        )
        beta_beta = np.array(
            [
                pair_to_index[(first + n_spatial, second + n_spatial)]
                for first, second in spatial_pairs
            ],
            dtype=int,
        )
        alpha_beta = np.array(
            [
                pair_to_index[(first, second + n_spatial)]
                for first in range(n_spatial)
                for second in range(n_spatial)
            ],
            dtype=int,
        )
        antisymmetric = np.zeros(
            (n_spatial * n_spatial, len(spatial_pairs)), dtype=float
        )
        symmetric_pairs = tuple((p, p) for p in range(n_spatial)) + spatial_pairs
        symmetric = np.zeros(
            (n_spatial * n_spatial, len(symmetric_pairs)), dtype=float
        )
        for column, (first, second) in enumerate(spatial_pairs):
            antisymmetric[first * n_spatial + second, column] = 1.0 / math.sqrt(2.0)
            antisymmetric[second * n_spatial + first, column] = -1.0 / math.sqrt(2.0)
        for column, (first, second) in enumerate(symmetric_pairs):
            if first == second:
                symmetric[first * n_spatial + second, column] = 1.0
            else:
                symmetric[first * n_spatial + second, column] = 1.0 / math.sqrt(2.0)
                symmetric[second * n_spatial + first, column] = 1.0 / math.sqrt(2.0)

        d_alpha_alpha = d2[np.ix_(alpha_alpha, alpha_alpha)]
        d_beta_beta = d2[np.ix_(beta_beta, beta_beta)]
        d_alpha_beta = d2[np.ix_(alpha_beta, alpha_beta)]
        d_triplet = antisymmetric.T @ d_alpha_beta @ antisymmetric
        constraints.extend(
            [
                d_alpha_alpha == d_beta_beta,
                d_triplet == d_alpha_alpha,
                antisymmetric.T @ d_alpha_beta @ symmetric == 0,
            ]
        )

    for first in range(n_modes):
        for third in range(n_modes):
            first_spin = int(first >= n_spatial)
            third_spin = int(third >= n_spatial)
            if first_spin != third_spin:
                continue
            for summed_spin, spin_particles in (
                (0, reference.n_alpha),
                (1, reference.n_beta),
            ):
                orbitals = (
                    range(0, n_spatial)
                    if summed_spin == 0
                    else range(n_spatial, n_modes)
                )
                contracted = sum(
                    (
                        _cvx_d_element(
                            d2, first, second, third, second, pair_to_index
                        )
                        for second in orbitals
                    ),
                    0.0,
                )
                factor = spin_particles - int(first_spin == summed_spin)
                constraints.append(contracted == factor * gamma[first, third])

    q_d_map, q_gamma_map, g_d_map, g_gamma_map, q_constant = _dqg_linear_maps(
        n_modes, reference.pairs
    )
    d2_vector = cp.vec(d2, order="C")
    gamma_vector = cp.vec(gamma, order="C")
    q2 = cp.reshape(
        q_d_map @ d2_vector + q_gamma_map @ gamma_vector + q_constant,
        (n_pairs, n_pairs),
        order="C",
    )
    if "Q" in positivity:
        q2_symmetric = 0.5 * (q2 + q2.T)
        if psd_blocks is None:
            constraints.append(q2_symmetric >> 0)
        else:
            for indices in psd_blocks["d2"]:
                constraints.append(q2_symmetric[np.ix_(indices, indices)] >> 0)

    g_dimension = n_modes * n_modes
    g2 = cp.reshape(
        g_d_map @ d2_vector + g_gamma_map @ gamma_vector,
        (g_dimension, g_dimension),
        order="C",
    )
    if "G" in positivity:
        g2_symmetric = 0.5 * (g2 + g2.T)
        if psd_blocks is None:
            constraints.append(g2_symmetric >> 0)
        else:
            for indices in psd_blocks["g"]:
                constraints.append(g2_symmetric[np.ix_(indices, indices)] >> 0)

    electronic_energy = cp.sum(cp.multiply(reference.one_body, gamma)) + cp.sum(
        cp.multiply(reference.two_body, d2)
    )
    if selection_objective == "energy":
        if selection_d2_target is not None:
            raise ValueError(
                "selection_d2_target is only valid with selection_objective='closest_d2'."
            )
        merit_function = electronic_energy
    elif selection_objective == "closest_d2":
        if selection_d2_target is None:
            raise ValueError(
                "selection_objective='closest_d2' requires selection_d2_target."
            )
        target = np.asarray(selection_d2_target, dtype=float)
        if target.shape != (n_pairs, n_pairs):
            raise ValueError(
                "selection_d2_target must have the same shape as the 2-RDM."
            )
        target = 0.5 * (target + target.T)
        merit_function = cp.sum_squares(d2 - target)
    elif selection_objective == "linear_rdm":
        if selection_d2_target is not None:
            raise ValueError(
                "selection_d2_target is only valid with "
                "selection_objective='closest_d2'."
            )
        merit_function = cp.Constant(0.0)
    else:
        if selection_d2_target is not None:
            raise ValueError(
                "selection_d2_target is not valid with "
                "selection_objective='affine_least_squares'."
            )
        objective_d2_map = sparse.csr_matrix(
            affine_objective.d2_map, dtype=float
        )
        objective_rows = objective_d2_map.shape[0]
        if objective_d2_map.shape[1] != n_pairs * n_pairs:
            raise ValueError("affine objective d2_map has an incompatible width.")
        objective_offset = np.asarray(
            affine_objective.offset, dtype=float
        ).reshape(-1)
        if len(objective_offset) != objective_rows:
            raise ValueError("affine objective offset has an incompatible length.")
        affine_residual = objective_d2_map @ d2_vector + objective_offset
        if affine_objective.gamma_map is not None:
            objective_gamma_map = sparse.csr_matrix(
                affine_objective.gamma_map, dtype=float
            )
            if objective_gamma_map.shape != (objective_rows, n_modes * n_modes):
                raise ValueError(
                    "affine objective gamma_map has an incompatible shape."
                )
            affine_residual = affine_residual + objective_gamma_map @ gamma_vector
        objective_scales = (
            np.ones(objective_rows, dtype=float)
            if affine_objective.scales is None
            else np.asarray(affine_objective.scales, dtype=float).reshape(-1)
        )
        if len(objective_scales) != objective_rows or np.any(objective_scales <= 0):
            raise ValueError("affine objective scales must be positive per row.")
        merit_function = cp.sum_squares(
            cp.multiply(1.0 / objective_scales, affine_residual)
        )
    if additional_d2_objective is not None:
        objective = np.asarray(additional_d2_objective, dtype=float)
        if objective.shape != (n_pairs, n_pairs):
            raise ValueError(
                "additional_d2_objective must have the same shape as the 2-RDM."
            )
        objective = 0.5 * (objective + objective.T)
        merit_function = merit_function + cp.sum(cp.multiply(objective, d2))
    if additional_gamma_objective is not None:
        objective = np.asarray(additional_gamma_objective, dtype=float)
        if objective.shape != (n_modes, n_modes):
            raise ValueError(
                "additional_gamma_objective must have the same shape as the 1-RDM."
            )
        objective = 0.5 * (objective + objective.T)
        merit_function = merit_function + cp.sum(cp.multiply(objective, gamma))
    options = _solver_options(
        solver, tolerance, max_iterations, verbose, solver_threads
    )
    fit_status: str | None = None
    slack_sum: float | None = None
    linear_fit_status: str | None = None
    linear_max_slack: float | None = None
    linear_d2_map: sparse.csr_matrix | None = None
    linear_gamma_map: sparse.csr_matrix | None = None
    linear_lower: np.ndarray | None = None
    linear_upper: np.ndarray | None = None
    linear_scales: np.ndarray | None = None
    fallback_d2: np.ndarray | None = None
    fallback_gamma: np.ndarray | None = None
    fallback_status: str | None = None
    shadow_error_positive: cp.Variable | None = None
    shadow_error_negative: cp.Variable | None = None
    weighted_inverse_standard_errors: np.ndarray | None = None
    weighted_observations: np.ndarray | None = None
    weighted_fit_optimum_rmse: float | None = None
    weighted_fit_final_rmse: float | None = None

    if weighted_fit_statistics is not None:
        statistics = weighted_fit_statistics
        rows = np.asarray(statistics.rows, dtype=int).reshape(-1)
        cols = np.asarray(statistics.cols, dtype=int).reshape(-1)
        factor = np.asarray(statistics.residual_factor, dtype=float)
        if (
            rows.shape != cols.shape
            or np.any(rows < 0)
            or np.any(cols < 0)
            or np.any(rows >= n_pairs)
            or np.any(cols >= n_pairs)
        ):
            raise ValueError("Weighted-fit statistic indices are invalid.")
        if factor.ndim != 2 or factor.shape[1] != len(rows) + 1:
            raise ValueError("Weighted-fit residual factor has an invalid shape.")
        observation_count = int(statistics.observation_count)
        if observation_count < 1:
            raise ValueError("Weighted-fit statistics need at least one observation.")
        variables = cp.hstack(
            [d2[int(row), int(col)] for row, col in zip(rows, cols)]
        )
        augmented = cp.hstack([variables, cp.Constant(np.ones(1))])
        normalized_residual = factor @ augmented
        residual_norm = cp.norm(normalized_residual, 2)
        if weighted_fit_rmse_cap is not None:
            constraints.append(
                residual_norm <= float(weighted_fit_rmse_cap)
            )
            fit_status = f"weighted_discrepancy_cap:{weighted_fit_rmse_cap:g}"
        else:
            fit_problem = cp.Problem(cp.Minimize(residual_norm), constraints)
            fit_problem.solve(**options)
            fit_status = f"weighted_least_squares:{fit_problem.status}"
            if (
                fit_problem.status not in OPTIMAL_STATUSES
                or residual_norm.value is None
                or d2.value is None
                or gamma.value is None
            ):
                raise RuntimeError(
                    f"Weighted shadow-fit SDP failed with status {fit_problem.status}."
                )
            optimum_norm = max(
                0.0, float(np.asarray(residual_norm.value).item())
            )
            weighted_fit_optimum_rmse = optimum_norm
            fallback_d2 = np.asarray(d2.value).copy()
            fallback_gamma = np.asarray(gamma.value).copy()
            fallback_status = str(fit_problem.status)
            fit_allowance = max(
                float(lexicographic_tolerance) * max(optimum_norm, 1.0),
                tolerance,
            )
            constraints.append(residual_norm <= optimum_norm + fit_allowance)
    elif shadow_data is not None:
        if shadow_error_weight is not None:
            shadow_error_positive = cp.Variable(
                (n_pairs, n_pairs), symmetric=True, name="shadow_error_positive"
            )
            shadow_error_negative = cp.Variable(
                (n_pairs, n_pairs), symmetric=True, name="shadow_error_negative"
            )
            constraints.extend(
                [shadow_error_positive >> 0, shadow_error_negative >> 0]
            )
            if initial_corrected_d2 is not None and initial_d2 is not None:
                delta = 0.5 * (
                    initial_corrected_d2
                    + initial_corrected_d2.T
                    - initial_d2
                    - initial_d2.T
                )
                eigenvalues, eigenvectors = np.linalg.eigh(delta)
                shadow_error_positive.value = (
                    eigenvectors * np.maximum(eigenvalues, 0.0)
                ) @ eigenvectors.T
                shadow_error_negative.value = (
                    eigenvectors * np.maximum(-eigenvalues, 0.0)
                ) @ eigenvectors.T
            corrected_d2 = d2 + shadow_error_positive - shadow_error_negative
            prediction = shadow_data.design @ cp.reshape(
                corrected_d2, (n_pairs * n_pairs,), order="C"
            )
            constraints.append(prediction == shadow_data.values)
            merit_function = merit_function + float(shadow_error_weight) * (
                cp.trace(shadow_error_positive) + cp.trace(shadow_error_negative)
            )
            fit_status = "paper_nuclear_norm"
        elif shadow_data.exact_constraints:
            prediction = shadow_data.design @ cp.reshape(
                d2, (n_pairs * n_pairs,), order="C"
            )
            constraints.append(prediction == shadow_data.values)
            fit_status = "exact"
            slack_sum = 0.0
        elif weighted_shadow_fit:
            if shadow_data.shots_per_basis < 1 or np.any(shadow_data.hits < 0):
                raise ValueError(
                    "weighted_shadow_fit requires finite-shot hit counts."
                )
            prediction = shadow_data.design @ cp.reshape(
                d2, (n_pairs * n_pairs,), order="C"
            )
            smoothed_probabilities = (
                shadow_data.hits.astype(float) + 0.5
            ) / (shadow_data.shots_per_basis + 1.0)
            variances = np.maximum(
                smoothed_probabilities * (1.0 - smoothed_probabilities)
                / shadow_data.shots_per_basis,
                shadow_variance_floor,
            )
            weighted_inverse_standard_errors = 1.0 / np.sqrt(variances)
            weighted_observations = np.asarray(shadow_data.values, dtype=float)
            normalized_residual = cp.multiply(
                weighted_inverse_standard_errors,
                prediction - weighted_observations,
            )
            residual_norm = cp.norm(normalized_residual, 2)
            observation_count = len(weighted_observations)
            if weighted_fit_rmse_cap is not None:
                constraints.append(
                    residual_norm
                    <= float(weighted_fit_rmse_cap) * math.sqrt(observation_count)
                )
                fit_status = f"weighted_discrepancy_cap:{weighted_fit_rmse_cap:g}"
            else:
                fit_problem = cp.Problem(cp.Minimize(residual_norm), constraints)
                fit_problem.solve(**options)
                fit_status = f"weighted_least_squares:{fit_problem.status}"
                if (
                    fit_problem.status not in OPTIMAL_STATUSES
                    or residual_norm.value is None
                    or d2.value is None
                    or gamma.value is None
                ):
                    raise RuntimeError(
                        f"Weighted shadow-fit SDP failed with status {fit_problem.status}."
                    )
                optimum_norm = max(
                    0.0, float(np.asarray(residual_norm.value).item())
                )
                weighted_fit_optimum_rmse = optimum_norm / math.sqrt(
                    observation_count
                )
                fallback_d2 = np.asarray(d2.value).copy()
                fallback_gamma = np.asarray(gamma.value).copy()
                fallback_status = str(fit_problem.status)
                fit_allowance = max(
                    float(lexicographic_tolerance) * max(optimum_norm, 1.0),
                    tolerance * math.sqrt(observation_count),
                )
                constraints.append(residual_norm <= optimum_norm + fit_allowance)
        else:
            prediction = shadow_data.design @ cp.reshape(
                d2, (n_pairs * n_pairs,), order="C"
            )
            slack = cp.Variable(
                len(shadow_data.values), nonneg=True, name="shadow_slack"
            )
            constraints.extend(
                [
                    prediction >= shadow_data.lower_bounds - slack,
                    prediction <= shadow_data.upper_bounds + slack,
                ]
            )
            fit_problem = cp.Problem(cp.Minimize(cp.sum(slack)), constraints)
            fit_problem.solve(**options)
            fit_status = fit_problem.status
            if fit_status not in OPTIMAL_STATUSES or slack.value is None:
                raise RuntimeError(f"Shadow-fit SDP failed with status {fit_status}.")
            slack_sum = max(0.0, float(np.sum(slack.value)))
            fallback_d2 = np.asarray(d2.value).copy()
            fallback_gamma = np.asarray(gamma.value).copy()
            fallback_status = str(fit_status)
            constraints.append(
                cp.sum(slack) <= slack_sum + max(lexicographic_tolerance, tolerance)
            )

    if linear_constraints is not None:
        d2_map = sparse.csr_matrix(linear_constraints.d2_map, dtype=float)
        row_count = d2_map.shape[0]
        if d2_map.shape[1] != n_pairs * n_pairs:
            raise ValueError("linear constraint d2_map has an incompatible width.")
        lower = np.asarray(linear_constraints.lower_bounds, dtype=float).reshape(-1)
        upper = np.asarray(linear_constraints.upper_bounds, dtype=float).reshape(-1)
        if len(lower) != row_count or len(upper) != row_count:
            raise ValueError("linear constraint bounds must match the map row count.")
        if np.any(lower > upper):
            raise ValueError("linear constraint lower bounds exceed upper bounds.")
        linear_d2_map = d2_map
        linear_gamma_map = None
        linear_lower = lower.copy()
        linear_upper = upper.copy()
        linear_prediction = d2_map @ d2_vector
        if linear_constraints.gamma_map is not None:
            gamma_map = sparse.csr_matrix(linear_constraints.gamma_map, dtype=float)
            if gamma_map.shape != (row_count, n_modes * n_modes):
                raise ValueError("linear constraint gamma_map has an incompatible shape.")
            linear_gamma_map = gamma_map
            linear_prediction = linear_prediction + gamma_map @ gamma_vector

        scales = (
            np.ones(row_count, dtype=float)
            if linear_constraints.scales is None
            else np.asarray(linear_constraints.scales, dtype=float).reshape(-1)
        )
        if len(scales) != row_count or np.any(scales <= 0.0):
            raise ValueError("linear constraint scales must be positive per row.")
        linear_scales = scales.copy()
        # Pair densities span many orders of magnitude between bonding and
        # vacuum grid points. Normalize hard and minimax bands alike so SCS's
        # absolute feasibility tolerance has the same physical meaning per row.
        inverse_scales = 1.0 / scales
        linear_prediction = cp.multiply(inverse_scales, linear_prediction)
        lower = lower * inverse_scales
        upper = upper * inverse_scales

        if linear_constraints.allow_minimax_relaxation:
            linear_slack = cp.Variable(nonneg=True, name="linear_band_max_slack")
            constraints.extend(
                [
                    linear_prediction >= lower - linear_slack,
                    linear_prediction <= upper + linear_slack,
                ]
            )
            linear_problem = cp.Problem(cp.Minimize(linear_slack), constraints)
            linear_problem.solve(**options)
            linear_fit_status = str(linear_problem.status)
            if (
                linear_problem.status not in OPTIMAL_STATUSES
                or linear_slack.value is None
                or d2.value is None
                or gamma.value is None
            ):
                raise RuntimeError(
                    f"Linear RDM band fit failed with status {linear_problem.status}."
                )
            linear_max_slack = max(0.0, float(linear_slack.value))
            fallback_d2 = np.asarray(d2.value).copy()
            fallback_gamma = np.asarray(gamma.value).copy()
            fallback_status = linear_fit_status
            constraints.append(
                linear_slack
                <= linear_max_slack
                + max(float(linear_lexicographic_tolerance), tolerance)
            )
        else:
            constraints.extend(
                [linear_prediction >= lower, linear_prediction <= upper]
            )
            linear_fit_status = "hard"
            linear_max_slack = 0.0

    if linear_fit_only:
        if (
            linear_constraints is None
            or not linear_constraints.allow_minimax_relaxation
            or fallback_d2 is None
            or fallback_gamma is None
        ):
            raise ValueError(
                "linear_fit_only requires minimax-relaxed linear constraints."
            )
        d2.value = fallback_d2
        gamma.value = fallback_gamma
        status = fallback_status
    else:
        energy_problem = cp.Problem(cp.Minimize(merit_function), constraints)
        energy_problem.solve(**options)
        status = energy_problem.status
        if status not in OPTIMAL_STATUSES and fallback_d2 is not None:
            d2.value = fallback_d2
            gamma.value = fallback_gamma
            status = fallback_status

    if status not in OPTIMAL_STATUSES or d2.value is None or gamma.value is None:
        raise RuntimeError(f"DQG SDP failed with status {status}.")
    d2_value = 0.5 * (np.asarray(d2.value) + np.asarray(d2.value).T)
    gamma_value = 0.5 * (np.asarray(gamma.value) + np.asarray(gamma.value).T)
    corrected_d2_value: np.ndarray | None = None
    shadow_error_trace: float | None = None
    if shadow_error_positive is not None and shadow_error_negative is not None:
        if shadow_error_positive.value is None or shadow_error_negative.value is None:
            raise RuntimeError("Nuclear-norm shadow error matrices have no solution.")
        positive_value = 0.5 * (
            np.asarray(shadow_error_positive.value)
            + np.asarray(shadow_error_positive.value).T
        )
        negative_value = 0.5 * (
            np.asarray(shadow_error_negative.value)
            + np.asarray(shadow_error_negative.value).T
        )
        corrected_d2_value = d2_value + positive_value - negative_value
        shadow_error_trace = float(
            np.trace(positive_value) + np.trace(negative_value)
        )
    energy = rdm_energy(
        d2_value,
        gamma_value,
        reference.one_body,
        reference.two_body,
        reference.nuclear_energy,
    )
    if (
        weighted_inverse_standard_errors is not None
        and weighted_observations is not None
    ):
        final_prediction = shadow_data.predict(d2_value)
        final_normalized_residual = weighted_inverse_standard_errors * (
            final_prediction - weighted_observations
        )
        weighted_fit_final_rmse = float(
            np.linalg.norm(final_normalized_residual)
            / math.sqrt(len(weighted_observations))
        )
    elif weighted_fit_statistics is not None:
        weighted_fit_final_rmse = weighted_fit_statistics.weighted_rmse(d2_value)
    linear_max_absolute_violation: float | None = None
    linear_max_normalized_violation: float | None = None
    if linear_d2_map is not None:
        linear_values = np.asarray(
            linear_d2_map @ d2_value.ravel(order="C")
        ).ravel()
        if linear_gamma_map is not None:
            linear_values += np.asarray(
                linear_gamma_map @ gamma_value.ravel(order="C")
            ).ravel()
        if linear_lower is None or linear_upper is None or linear_scales is None:
            raise RuntimeError("Linear-constraint diagnostics were not initialized.")
        linear_excess = np.maximum(
            np.maximum(linear_lower - linear_values, linear_values - linear_upper),
            0.0,
        )
        linear_max_absolute_violation = float(
            np.max(linear_excess, initial=0.0)
        )
        linear_max_normalized_violation = float(
            np.max(linear_excess / linear_scales, initial=0.0)
        )
    return SDPResult(
        d2=d2_value,
        gamma=gamma_value,
        energy=energy,
        status=str(status),
        fit_status=str(fit_status) if fit_status is not None else None,
        slack_sum=slack_sum,
        solver=solver,
        linear_fit_status=linear_fit_status,
        linear_max_slack=linear_max_slack,
        linear_max_absolute_violation=linear_max_absolute_violation,
        linear_max_normalized_violation=linear_max_normalized_violation,
        corrected_d2=corrected_d2_value,
        shadow_error_trace=shadow_error_trace,
        shadow_error_weight=shadow_error_weight,
        weighted_fit_optimum_rmse=weighted_fit_optimum_rmse,
        weighted_fit_final_rmse=weighted_fit_final_rmse,
    )


def linear_shadow_fit(
    reference: MolecularReference,
    shadow_data: ShadowData,
    ridge: float = 1e-8,
) -> tuple[np.ndarray, np.ndarray]:
    """Fit the same shadows without positivity constraints.

    This is an unconstrained linear least-squares diagnostic, not the analytic
    fermionic-classical-shadow inverse used for the paper's FCS curve.
    """

    n_pairs = len(reference.pairs)
    n_spatial = reference.n_spatial_orbitals
    pair_alpha_count = np.array(
        [int(first < n_spatial) + int(second < n_spatial) for first, second in reference.pairs]
    )
    variables = [
        (row, col)
        for row in range(n_pairs)
        for col in range(row, n_pairs)
        if pair_alpha_count[row] == pair_alpha_count[col]
    ]
    primary_columns = np.array(
        [row * n_pairs + col for row, col in variables], dtype=int
    )
    secondary_columns = np.array(
        [col * n_pairs + row for row, col in variables], dtype=int
    )
    design = shadow_data.design[:, primary_columns].toarray()
    off_diagonal = primary_columns != secondary_columns
    design[:, off_diagonal] += shadow_data.design[
        :, secondary_columns[off_diagonal]
    ].toarray()

    constraints = np.zeros((3, len(variables)), dtype=float)
    targets = np.array(
        [
            math.comb(reference.n_alpha, 2),
            reference.n_alpha * reference.n_beta,
            math.comb(reference.n_beta, 2),
        ],
        dtype=float,
    )
    for index, (row, col) in enumerate(variables):
        if row == col:
            constraints[2 - pair_alpha_count[row], index] = 1.0

    gram = design.T @ design + ridge * np.eye(len(variables))
    kkt = np.block(
        [
            [gram, constraints.T],
            [constraints, np.zeros((constraints.shape[0], constraints.shape[0]))],
        ]
    )
    right_hand_side = np.concatenate([design.T @ shadow_data.values, targets])
    solution = np.linalg.lstsq(kkt, right_hand_side, rcond=None)[0][: len(variables)]
    d2 = np.zeros((n_pairs, n_pairs), dtype=float)
    for value, (row, col) in zip(solution, variables):
        d2[row, col] = value
        d2[col, row] = value
    gamma = contract_one_rdm(
        d2, reference.n_spin_orbitals, reference.n_electrons, reference.pairs
    )
    return d2, gamma


def reconstruction_metrics(
    d2: np.ndarray,
    gamma: np.ndarray,
    reference: MolecularReference,
    shadow_data: ShadowData | None = None,
) -> dict[str, float]:
    """Compute energy, 2-RDM error, residual, and representability diagnostics."""

    d_matrix, q_matrix, g_matrix = dqg_matrices(d2, gamma, reference.pairs)
    metrics = {
        "energy": rdm_energy(
            d2,
            gamma,
            reference.one_body,
            reference.two_body,
            reference.nuclear_energy,
        ),
        "energy_error": abs(
            rdm_energy(
                d2,
                gamma,
                reference.one_body,
                reference.two_body,
                reference.nuclear_energy,
            )
            - reference.exact_energy
        ),
        "d2_frobenius_error": float(np.linalg.norm(d2 - reference.exact_d2)),
        "d2_normalized_frobenius_error": float(
            np.linalg.norm(d2 - reference.exact_d2) / np.trace(reference.exact_d2)
        ),
        "gamma_frobenius_error": float(np.linalg.norm(gamma - reference.exact_gamma)),
        "trace_d2": float(np.trace(d2)),
        "min_eigenvalue_d": float(np.linalg.eigvalsh(d_matrix)[0]),
        "min_eigenvalue_q": float(np.linalg.eigvalsh(q_matrix)[0]),
        "min_eigenvalue_g": float(np.linalg.eigvalsh(g_matrix)[0]),
    }
    if shadow_data is not None:
        predicted = shadow_data.predict(d2)
        metrics["shadow_rmse"] = float(
            np.sqrt(np.mean((predicted - shadow_data.values) ** 2))
        )
        metrics["exact_sampling_rmse"] = float(
            np.sqrt(np.mean((shadow_data.exact_values - shadow_data.values) ** 2))
        )
    return metrics


def save_npz(
    path: str | Path,
    reference: MolecularReference,
    shadow_data: ShadowData,
    reconstructions: dict[str, tuple[np.ndarray, np.ndarray]] | None = None,
    additional_arrays: dict[str, np.ndarray] | None = None,
) -> None:
    """Persist raw rotations and finite-shot observations for an auditable run."""

    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    arrays = {
        "exact_d2": reference.exact_d2,
        "exact_gamma": reference.exact_gamma,
        "rotations": np.asarray(shadow_data.rotations),
        "pair_vectors": shadow_data.pair_vectors,
        "design_data": shadow_data.design.data,
        "design_indices": shadow_data.design.indices,
        "design_indptr": shadow_data.design.indptr,
        "design_shape": np.asarray(shadow_data.design.shape),
        "hits": shadow_data.hits,
        "values": shadow_data.values,
        "lower_bounds": shadow_data.lower_bounds,
        "upper_bounds": shadow_data.upper_bounds,
        "shots_per_basis": np.asarray(shadow_data.shots_per_basis),
        "exact_values": shadow_data.exact_values,
        "exact_constraints": np.asarray(shadow_data.exact_constraints),
    }
    if shadow_data.occupations is not None:
        arrays["occupations"] = shadow_data.occupations
    for name, (d2, gamma) in (reconstructions or {}).items():
        arrays[f"{name}_d2"] = d2
        arrays[f"{name}_gamma"] = gamma
    arrays.update(additional_arrays or {})
    np.savez_compressed(output, **arrays)


def load_shadow_npz(path: str | Path) -> ShadowData:
    """Load the auditable shadow arrays written by :func:`save_npz`."""

    with np.load(Path(path)) as arrays:
        required = {
            "rotations",
            "pair_vectors",
            "design_data",
            "design_indices",
            "design_indptr",
            "design_shape",
            "hits",
            "values",
            "lower_bounds",
            "upper_bounds",
            "shots_per_basis",
            "exact_values",
            "exact_constraints",
        }
        missing = required.difference(arrays.files)
        if missing:
            raise ValueError(
                f"Shadow NPZ is missing arrays: {', '.join(sorted(missing))}."
            )
        design = sparse.csr_matrix(
            (
                np.asarray(arrays["design_data"], dtype=float),
                np.asarray(arrays["design_indices"], dtype=int),
                np.asarray(arrays["design_indptr"], dtype=int),
            ),
            shape=tuple(int(value) for value in arrays["design_shape"]),
        )
        return ShadowData(
            rotations=tuple(np.asarray(item, dtype=float) for item in arrays["rotations"]),
            pair_vectors=np.asarray(arrays["pair_vectors"], dtype=float),
            design=design,
            values=np.asarray(arrays["values"], dtype=float),
            lower_bounds=np.asarray(arrays["lower_bounds"], dtype=float),
            upper_bounds=np.asarray(arrays["upper_bounds"], dtype=float),
            hits=np.asarray(arrays["hits"], dtype=int),
            shots_per_basis=int(np.asarray(arrays["shots_per_basis"]).item()),
            exact_values=np.asarray(arrays["exact_values"], dtype=float),
            exact_constraints=bool(np.asarray(arrays["exact_constraints"]).item()),
            occupations=(
                np.asarray(arrays["occupations"], dtype=np.uint64)
                if "occupations" in arrays.files
                else None
            ),
        )
